#!/usr/bin/env bash
# Question 3: Deployment ${Q3_APP} does not serve its page. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

kubectl create namespace "${Q3_NS}" >/dev/null 2>&1 || kubectl get namespace "${Q3_NS}" >/dev/null
timeout 60 bash -c "until kubectl -n '${Q3_NS}' get serviceaccount default >/dev/null 2>&1; do sleep 1; done"
kubectl apply -f - <<EOF
apiVersion: v1
kind: ConfigMap
metadata:
  name: ${Q3_APP}-content
  namespace: ${Q3_NS}
data:
  index.html: "<h1>${Q3_APP} is up</h1>"
---
apiVersion: v1
kind: Secret
metadata:
  name: ${Q3_APP}-secret
  namespace: ${Q3_NS}
stringData:
  token: s3cr3t-${Q3_APP}
---
apiVersion: apps/v1
kind: Deployment
metadata:
  name: ${Q3_APP}
  namespace: ${Q3_NS}
spec:
  replicas: 0
  selector:
    matchLabels: { app: ${Q3_APP} }
  template:
    metadata:
      labels: { app: ${Q3_APP} }
    spec:
      containers:
        - name: web
          image: nginx:1.27-alpine
          ports: [{ containerPort: 80 }]
          readinessProbe:
            httpGet: { path: /, port: 80 }
            periodSeconds: 5
          volumeMounts:
            - { name: content, mountPath: /usr/share/nginx/html }
            - { name: secret, mountPath: /etc/${Q3_APP}, readOnly: true }
      volumes:
        - name: content
          configMap: { name: ${Q3_APP}-content }
        - name: secret
          secret:
            secretName: ${Q3_APP}-secret
            items: [{ key: token, path: token }]
EOF

case "${Q3_FAULT}" in
  configmap-volume-missing)
    kubectl -n "${Q3_NS}" patch deployment "${Q3_APP}" --type=json -p '[{"op":"replace","path":"/spec/template/spec/volumes/0/configMap/name","value":"'"${Q3_APP}"'-contents"}]'
    ;;
  secret-items-key)
    kubectl -n "${Q3_NS}" patch deployment "${Q3_APP}" --type=json -p '[{"op":"replace","path":"/spec/template/spec/volumes/1/secret/items/0/key","value":"api-token"}]'
    ;;
  mount-path)
    kubectl -n "${Q3_NS}" patch deployment "${Q3_APP}" --type=json -p '[{"op":"replace","path":"/spec/template/spec/containers/0/volumeMounts/0/mountPath","value":"/usr/share/nginx"}]'
    ;;
  run-as-non-root)
    kubectl -n "${Q3_NS}" patch deployment "${Q3_APP}" --type=json -p '[{"op":"add","path":"/spec/template/spec/containers/0/securityContext","value":{"runAsNonRoot":true}}]'
    ;;
  readonly-root)
    kubectl -n "${Q3_NS}" patch deployment "${Q3_APP}" --type=json -p '[{"op":"add","path":"/spec/template/spec/containers/0/securityContext","value":{"readOnlyRootFilesystem":true}}]'
    ;;
  *)
    echo "unknown fault" >&2
    exit 1
    ;;
esac

kubectl -n "${Q3_NS}" scale "deployment/${Q3_APP}" --replicas=2
notready=0
for _ in $(seq 1 10); do
  states="$(kubectl -n "${Q3_NS}" get pods -l "app=${Q3_APP}" -o jsonpath='{range .items[*]}{.status.phase} {.status.conditions[?(@.type=="Ready")].status} {.status.conditions[?(@.type=="PodScheduled")].status} {.status.containerStatuses[0].state.waiting.reason} {.status.containerStatuses[0].restartCount}{"\n"}{end}' 2>/dev/null)"
  if grep -qE '(ErrImagePull|ImagePullBackOff|CrashLoopBackOff|CreateContainerConfigError|CreateContainerError|RunContainerError)|[1-9][0-9]*$|^[A-Za-z]+ [A-Za-z]* False' <<< "$states"; then break; fi
  if kubectl -n "${Q3_NS}" get events --field-selector reason=FailedMount -o name 2>/dev/null | grep -q .; then break; fi
  if grep -qE '^Running False' <<< "$states"; then
    notready=$((notready + 1))
    (( notready >= 3 )) && break
  else
    notready=0
  fi
  sleep 2
done
[[ "$(kubectl -n "${Q3_NS}" get deployment "${Q3_APP}" -o jsonpath='{.status.readyReplicas}')" != 2 ]] || { echo "${Q3_APP} is still healthy" >&2; exit 1; }
